css:
.d-validation-summary{width:100%;max-width:430px;min-width:0;color:var(--ink);font:inherit;font-size:14px;line-height:1.5;overflow-wrap:anywhere}
.d-validation-summary *,.d-validation-summary *::before,.d-validation-summary *::after{box-sizing:border-box}
.d-validation-summary [hidden]{display:none!important}
.d-validation-summary .d-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0}
.d-validation-summary .d-note{display:block;margin:8px 0 0;color:var(--muted);font-size:12px;min-height:1.5em}
.d-validation-summary label{display:block;margin:8px 0}
.d-validation-summary input,.d-validation-summary select,.d-validation-summary textarea,.d-validation-summary button{font:inherit;color:inherit;max-width:100%;min-width:0}
.d-validation-summary input:not([type=checkbox]):not([type=radio]),.d-validation-summary select,.d-validation-summary textarea{width:100%;padding:8px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper)}
.d-validation-summary button{padding:6px 10px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper);cursor:pointer}
.d-validation-summary button:disabled{opacity:.5;cursor:default}
.d-validation-summary :focus-visible{outline:2px solid var(--ink);outline-offset:3px}
.d-validation-summary [aria-invalid=true]{border-color:var(--warn)!important}
.d-validation-summary .d-scroll{max-width:100%;overflow:auto}
.d-validation-summary table{width:100%;border-collapse:collapse;font-size:12px;text-align:left}
.d-validation-summary th,.d-validation-summary td{padding:7px;border-bottom:1px solid var(--line);vertical-align:top}
.d-validation-summary caption{text-align:left;font-weight:600;margin-bottom:8px}
.d-validation-summary progress{width:100%;accent-color:var(--ink)}
.d-validation-summary pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}
.d-validation-summary h3,.d-validation-summary p{margin:8px 0}
.d-validation-summary [aria-pressed=true],.d-validation-summary [aria-selected=true]{border-color:var(--ink);font-weight:650}
.d-validation-summary .d-grow{flex:1;min-width:100px}
.d-validation-summary summary{cursor:pointer;padding:6px 0}
.d-validation-summary ul,.d-validation-summary ol{padding-left:24px}

init:
root => {
 const q = selector => root.querySelector(selector);
 const qa = selector => [...root.querySelectorAll(selector)];
 const say = text => { const out = q('[data-out]'); if (out) out.textContent = text; };
 ((root,q,qa,say)=>{q('[data-form]').onsubmit=event=>{event.preventDefault();const errors=[];for(const [selector,message] of [['[data-name]','填写项目名称'],['[data-email]','填写有效邮箱']]){const field=q(selector),bad=!field.value.trim()||!field.validity.valid;field.setAttribute('aria-invalid',String(bad));if(bad)errors.push({field,message});}q('[data-errors]').replaceChildren(...errors.map(({field,message})=>{const li=document.createElement('li'),button=document.createElement('button');button.type='button';button.textContent=message;button.onclick=()=>field.focus();li.append(button);return li;}));q('[data-summary]').hidden=!errors.length;if(errors.length)q('[data-summary]').focus();say(errors.length?errors.length+' 项需要修正':'演示校验通过，可提交');};})(root, q, qa, say);
}
